# Private coordination labels are unnecessary in user-facing artifacts.
def clean(v):
 if isinstance(v,str):
  return v.replace('parent and independent challenger','mathematical and independent reviewers').replace('parent and independent adversarial reviewer','mathematical and independent reviewers').replace('parent and independent reviewer','mathematical and independent reviewers').replace('parent reviewers','mathematical reviewers').replace('adversarial and parent reviewers','independent mathematical reviewers').replace('Parent review','Mathematical review').replace('parent review','mathematical review').replace('matrix lead incorporates it','full matrix manuscript contains the proof').replace('matrix lead incorporates proof','full matrix manuscript contains the proof').replace('matrix lead incorporates it','full matrix manuscript contains it')
 if isinstance(v,list):return [clean(x) for x in v]
 if isinstance(v,dict):return {k:clean(x) for k,x in v.items()}
 return v
